// Simform fork: Microsoft icon packs (Azure, Microsoft 365, Entra, Fabric,
// Dynamics 365) usable as node marks through the existing `brand` field.
//
// The curated SVG files live unmodified in `icon-packs/<pack>/` and are indexed
// by `icon-packs/catalog.json` (generated by `scripts/sync-icon-packs.mjs`).
// Microsoft's terms allow the icons in architecture diagrams but not altered
// artwork, so this module never recolours or edits shapes: it only wraps the
// original markup and namespaces its internal ids so several icons (or the same
// icon twice) can share one HTML document without gradient collisions.
import { createHash } from 'node:crypto';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { containedBy } from './path-semantics.mjs';

export const ICON_PACKS_ROOT = path.resolve(path.dirname(fileURLToPath(import.meta.url)), '../../icon-packs');
export const ICON_CATALOG_FILE = path.join(ICON_PACKS_ROOT, 'catalog.json');

const ALLOWED_ELEMENTS = new Set([
  'svg', 'g', 'defs', 'path', 'rect', 'circle', 'ellipse', 'line', 'polyline', 'polygon',
  'lineargradient', 'radialgradient', 'stop', 'clippath', 'mask', 'title', 'desc',
]);
const MAX_ICON_BYTES = 256 * 1024;

let catalogCache = null;
let lookupCache = null;

function lookupForms(value) {
  const raw = String(value ?? '').trim().toLocaleLowerCase('en-US');
  if (!raw) return [];
  const dashed = raw.replace(/[\s_]+/g, '-');
  const compact = raw.replace(/[\s_.-]+/g, '');
  return [...new Set([raw, dashed, compact])];
}

export function loadIconCatalog() {
  if (catalogCache) return catalogCache;
  let parsed = { schemaVersion: 1, packs: {}, icons: [] };
  try {
    parsed = JSON.parse(fs.readFileSync(ICON_CATALOG_FILE, 'utf8'));
  } catch (error) {
    if (error?.code !== 'ENOENT') throw error;
  }
  catalogCache = parsed;
  return catalogCache;
}

/** Test hook: forget the cached catalog so a fixture can replace it. */
export function resetIconCatalogCache() {
  catalogCache = null;
  lookupCache = null;
}

function lookupTable() {
  if (lookupCache) return lookupCache;
  const table = new Map();
  const { icons } = loadIconCatalog();
  // Ids win, then hand-curated aliases (aliases.json), then titles, then
  // derived aliases, so a generic word never shadows a deliberate choice.
  for (const pass of ['id', 'pinned', 'title', 'alias']) {
    for (const icon of icons) {
      const values = pass === 'id' ? [icon.id]
        : (pass === 'pinned' ? icon.pinned || []
          : (pass === 'title' ? [icon.title] : icon.aliases || []));
      for (const value of values) {
        for (const form of lookupForms(value)) {
          if (!table.has(form)) table.set(form, icon);
        }
      }
    }
  }
  lookupCache = table;
  return table;
}

export function findPackIcon(value) {
  for (const form of lookupForms(value)) {
    const icon = lookupTable().get(form);
    if (icon) return icon;
  }
  return null;
}

export function packSourceUrl(icon) {
  return loadIconCatalog().packs?.[icon.pack]?.page || null;
}

export function listPackIcons(query = '') {
  const needle = String(query).trim().toLocaleLowerCase('en-US');
  return loadIconCatalog().icons.filter((icon) => {
    if (!needle) return true;
    return [icon.id, icon.title, icon.pack, icon.category, ...(icon.aliases || [])]
      .some((value) => String(value).toLocaleLowerCase('en-US').includes(needle));
  }).map((icon) => ({
    id: icon.id,
    title: icon.title,
    category: `${icon.pack}/${icon.category}`,
    aliases: icon.aliases || [],
    domains: [],
    pack: icon.pack,
  }));
}

export function suggestPackIcons(value, limit = 5) {
  const needle = lookupForms(value)[0] || '';
  if (!needle) return [];
  const words = needle.split(/[\s-]+/).filter((word) => word.length > 1);
  return loadIconCatalog().icons.map((icon) => {
    const haystack = [icon.id, icon.title, ...(icon.aliases || [])].join(' ').toLocaleLowerCase('en-US');
    const score = words.filter((word) => haystack.includes(word)).length;
    return { id: icon.id, score };
  }).filter((entry) => entry.score > 0)
    .sort((left, right) => right.score - left.score || left.id.localeCompare(right.id))
    .slice(0, limit)
    .map((entry) => entry.id);
}

function numberAttr(text, name) {
  const match = text.match(new RegExp(`\\s${name}="\\s*([0-9.]+)\\s*(?:px)?\\s*"`));
  return match ? Number(match[1]) : null;
}

/**
 * Validate one Microsoft icon SVG and split it into viewBox and inner markup.
 * Pure function shared by the sync script, `--check`, and the renderer.
 */
export function inspectIconSvg(text) {
  if (typeof text !== 'string' || !text.trim()) return { ok: false, reason: 'empty file' };
  if (Buffer.byteLength(text) > MAX_ICON_BYTES) return { ok: false, reason: 'file is larger than 256 KiB' };
  if (/<!doctype|<!entity|<!\[cdata\[/i.test(text)) return { ok: false, reason: 'DOCTYPE, ENTITY or CDATA is not allowed' };
  const body = text.replace(/^﻿/, '').replace(/^\s*<\?xml[^>]*\?>/i, '').replace(/<!--[\s\S]*?-->/g, '');
  if (/<\?/.test(body)) return { ok: false, reason: 'processing instructions are not allowed' };
  const element = /<\/?([a-zA-Z][\w:.-]*)/g;
  let match;
  while ((match = element.exec(body))) {
    if (!ALLOWED_ELEMENTS.has(match[1].toLocaleLowerCase('en-US'))) {
      return { ok: false, reason: `element <${match[1]}> is not allowed` };
    }
  }
  if (/\son[a-z]+\s*=/i.test(body)) return { ok: false, reason: 'event handler attribute is not allowed' };
  if (/javascript:|data:|expression\s*\(|@import/i.test(body)) return { ok: false, reason: 'script or data URL is not allowed' };
  for (const ref of body.matchAll(/(?:xlink:)?href\s*=\s*"([^"]*)"/g)) {
    if (!ref[1].startsWith('#')) return { ok: false, reason: `external reference "${ref[1].slice(0, 40)}" is not allowed` };
  }
  for (const ref of body.matchAll(/url\(\s*['"]?([^)'"]*)/g)) {
    if (!ref[1].startsWith('#')) return { ok: false, reason: `external url() "${ref[1].slice(0, 40)}" is not allowed` };
  }
  const open = body.match(/<svg\b([^>]*)>/i);
  const close = body.lastIndexOf('</svg>');
  if (!open || close === -1) return { ok: false, reason: 'no root <svg> element' };
  const rootAttrs = ` ${open[1]}`;
  let viewBox = null;
  const declared = rootAttrs.match(/\sviewBox="\s*([-0-9.]+)[\s,]+([-0-9.]+)[\s,]+([0-9.]+)[\s,]+([0-9.]+)\s*"/);
  if (declared) viewBox = declared.slice(1, 5).map(Number);
  else {
    const width = numberAttr(rootAttrs, 'width');
    const height = numberAttr(rootAttrs, 'height');
    if (width && height) viewBox = [0, 0, width, height];
  }
  if (!viewBox || !(viewBox[2] > 0) || !(viewBox[3] > 0)) return { ok: false, reason: 'missing viewBox and width/height' };
  const inner = body
    .slice(open.index + open[0].length, close)
    .replace(/<title>[\s\S]*?<\/title>/gi, '')
    .replace(/<desc>[\s\S]*?<\/desc>/gi, '')
    .replace(/\sdata-name="[^"]*"/g, '')
    .trim();
  if (!inner) return { ok: false, reason: 'no drawing content' };
  return { ok: true, viewBox, inner };
}

function escapeRegExp(value) {
  return value.replace(/[.*+?^${}()|[\]\\]/g, '\\$&');
}

/** Prefix every internal id (and its references) so repeated inlining is safe. */
export function namespaceSvgIds(markup, prefix) {
  const ids = [...new Set([...markup.matchAll(/\sid="([^"]+)"/g)].map((match) => match[1]))];
  if (!ids.length) return markup;
  let result = markup;
  for (const id of ids.sort((left, right) => right.length - left.length)) {
    const safe = escapeRegExp(id);
    result = result
      .replace(new RegExp(`(\\sid=")${safe}(")`, 'g'), `$1${prefix}${id}$2`)
      .replace(new RegExp(`(url\\(\\s*['"]?#)${safe}(['"]?\\s*\\))`, 'g'), `$1${prefix}${id}$2`)
      .replace(new RegExp(`((?:xlink:)?href\\s*=\\s*"#)${safe}(")`, 'g'), `$1${prefix}${id}$2`);
  }
  return result;
}

/** Read, verify and prepare one catalogue icon for inlining. */
export function loadPackIcon(icon, scope) {
  const file = path.resolve(ICON_PACKS_ROOT, icon.file);
  if (containedBy(ICON_PACKS_ROOT, file).status !== 'match') throw new Error(`Icon file escapes icon-packs: ${icon.file}`);
  const bytes = fs.readFileSync(file);
  const digest = createHash('sha256').update(bytes).digest('hex');
  if (digest !== icon.sha256) throw new Error(`Icon ${icon.id} does not match its catalogue digest; run "npm --prefix archify run check:icon-packs".`);
  const inspected = inspectIconSvg(bytes.toString('utf8'));
  if (!inspected.ok) throw new Error(`Icon ${icon.id} is not renderable: ${inspected.reason}`);
  const markup = namespaceSvgIds(inspected.inner, `${scope}-`);
  // Generic (Lucide) icons are line art: the presentation attributes live on the
  // root <svg>, which is stripped, so they are carried on a wrapper group. The
  // stroke is currentColor, so the node's own colour reaches the glyph.
  if (icon.pack === 'generic') {
    return {
      viewBox: inspected.viewBox,
      line: true,
      markup: `<g fill="none" stroke="currentColor" stroke-width="1.75" stroke-linecap="round" stroke-linejoin="round">${markup}</g>`,
    };
  }
  return { viewBox: inspected.viewBox, markup };
}
